// pushBootstrapConfigKey is the local git-config key recording that every
// resolved push target for the user's remote has already been observed to carry
// at least one branch. Its value is a fingerprint of that confirmed target set.
const pushBootstrapConfigKey = "entire.checkpointPushBootstrap"

// pushTargetsFingerprint returns a stable, order-independent digest of the push
// targets. Hashing keeps the stored value bounded and avoids duplicating a push
// URL (which can embed credentials) into a second config key.
func pushTargetsFingerprint(targets []string) string {
	sorted := append([]string(nil), targets...)
	sort.Strings(sorted)
	sum := sha256.Sum256([]byte(strings.Join(sorted, "\n")))
	return hex.EncodeToString(sum[:])
}

// readLocalGitConfig returns the local git-config value for key, or "" if it is
// unset or unreadable.
func readLocalGitConfig(ctx context.Context, dir, key string) string {
	cmd := exec.CommandContext(ctx, "git", "config", "--local", "--get", key)
	if dir != "" {
		cmd.Dir = dir
	}
	out, err := cmd.Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

// setLocalGitConfig writes key=value to local git config. Best-effort: a failure
// only means the next push re-runs the (correct) network probe, so it warns
// rather than surfacing an error into the push path.
func setLocalGitConfig(ctx context.Context, dir, key, value string) {
	cmd := exec.CommandContext(ctx, "git", "config", "--local", key, value)
	if dir != "" {
		cmd.Dir = dir
	}
	if out, err := cmd.CombinedOutput(); err != nil {
		logging.Warn(ctx, "failed to persist checkpoint push bootstrap marker",
			slog.String("key", key),
			slog.String("output", strings.TrimSpace(string(out))),
			slog.String("error", err.Error()),
		)
	}
}

